import{_ as t,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Windows 11 migration readiness — enumerated source for the Windows 11 Pro Migration Readiness Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/windows-11-readiness-question-set.md","filePath":"frameworks/windows-11-readiness-question-set.md"}'),n={name:"frameworks/windows-11-readiness-question-set.md"};function o(s,e,i,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="windows-11-migration-readiness-—-enumerated-source-for-the-windows-11-pro-migration-readiness-assessment" tabindex="-1">Windows 11 migration readiness — enumerated source for the Windows 11 Pro Migration Readiness Assessment <a class="header-anchor" href="#windows-11-migration-readiness-—-enumerated-source-for-the-windows-11-pro-migration-readiness-assessment" aria-label="Permalink to &quot;Windows 11 migration readiness — enumerated source for the Windows 11 Pro Migration Readiness Assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>win11.readiness.yaml</code> is a readiness review for moving a fleet of Windows client devices to Windows 11: planning, hardware eligibility, applications, management and update control, the security baseline, and operations. It is Scout&#39;s counterpart to Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/1020523c-e223-432c-8be1-ebbb348f8130/" target="_blank" rel="noreferrer">Windows 11 Pro Migration Readiness Assessment</a>. <code>src/assess/rules/win11.readiness.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Every item is a <strong>manual</strong> question answered with <code>-AssessmentAnswers</code>, because Scout does not read client devices. Azure Arc-enabled servers and Azure virtual machines are not client devices and are never used as evidence for these items.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/1020523c-e223-432c-8be1-ebbb348f8130/" target="_blank" rel="noreferrer">Windows 11 Pro Migration Readiness Assessment</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Windows 11 planning, readiness and servicing guidance on Microsoft Learn, current as of the extraction date; no published version number</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Pages marked <code>fetched</code> in the source list were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Pages marked <code>search excerpt</code> were read through <code>microsoft_docs_search</code> excerpts on the same day, not in full. The Microsoft Graph interfaces named in the last section were checked against Learn reference pages the same day. No device or Intune tenant was read.</td></tr></tbody></table><h2 id="product-status" tabindex="-1">Product status <a class="header-anchor" href="#product-status" aria-label="Permalink to &quot;Product status&quot;">​</a></h2><p>Checked against Microsoft Learn on 2026-11-25.</p><ul><li><strong>Windows 10 has reached end of support.</strong> Windows 10 version 22H2 was the final version, and support ended on 2025-10-14. Devices still on Windows 10 no longer receive free security updates; the paid Extended Security Updates (ESU) programme is the only route to updates. The migration is therefore no longer ahead of a deadline, and WIN11-PL-05 asks what has been decided for each device that remains.</li><li><strong>Lifecycle of the editions.</strong> Learn states that Home, Pro, Pro for Workstations and Pro for Education editions of Windows 11 receive 24 months of support from the general availability date of a version, and Enterprise and Education editions 36 months. WIN11-PL-04 asks whether the servicing strategy allows for this.</li><li><strong>Tooling.</strong> Readiness is read from Intune endpoint analytics (Work from anywhere). Windows Autopatch supports Windows 11 Pro among its editions, with licence prerequisites such as Microsoft 365 Business Premium or Windows Enterprise E3 (WIN11-MG-04).</li><li><strong>Nothing is retired or renamed</strong> in the guidance used here.</li></ul><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The questions are Scout-derived, not Microsoft&#39;s.</strong> The assessment&#39;s question text is not published, so the items below are Scout&#39;s reading of the guidance listed above. The <code>WIN11-*</code> IDs, and the assignment of an item to a group, are Scout&#39;s own.</p><p><strong>Scout does not read this product&#39;s data yet.</strong> Scout reads Azure (Resource Graph and ARM) and one Microsoft Entra policy. It does not read Intune, Configuration Manager or Windows client devices, and the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code> holds no client device data. Azure Arc-enabled servers (<code>domains.hybrid.arcServers</code>) and Azure virtual machines are servers and workloads, not the user devices this assessment is about, so they are not used as evidence. Every rule is therefore <code>manual: true</code> with <code>query: null</code>: it is exported as a question by <code>Export-ScoutAssessmentQuestion</code>, answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>), and stays Manual and out of the score until answered.</p><p>Sources:</p><ul><li>[PLAN] <a href="https://learn.microsoft.com/windows/whats-new/windows-11-plan" target="_blank" rel="noreferrer">Plan for Windows 11</a> -- fetched</li><li>[REQ] <a href="https://learn.microsoft.com/windows/whats-new/windows-11-requirements" target="_blank" rel="noreferrer">Windows 11 requirements</a> -- fetched</li><li>[RDY] <a href="https://learn.microsoft.com/windows/deployment/update/plan-define-readiness" target="_blank" rel="noreferrer">Define readiness criteria</a> -- fetched</li><li>[INF] <a href="https://learn.microsoft.com/windows/deployment/update/eval-infra-tools" target="_blank" rel="noreferrer">Evaluate infrastructure and tools</a> -- fetched</li><li>[STRAT] <a href="https://learn.microsoft.com/windows/deployment/update/plan-define-strategy" target="_blank" rel="noreferrer">Define update strategy with a calendar</a> -- fetched</li><li>[TEST] <a href="https://learn.microsoft.com/windows/compatibility/windows-11/testing-guidelines" target="_blank" rel="noreferrer">Windows 11 application compatibility testing guidelines</a> -- fetched</li><li>[WFA] <a href="https://learn.microsoft.com/intune/endpoint-analytics/work-from-anywhere" target="_blank" rel="noreferrer">Work from anywhere report (endpoint analytics, Windows 11 hardware readiness)</a> -- search excerpt</li><li>[UPG] <a href="https://learn.microsoft.com/intune/device-updates/windows/upgrade-to-windows-11" target="_blank" rel="noreferrer">Upgrade devices to Windows 11 using feature updates (Intune)</a> -- search excerpt</li><li>[AP] <a href="https://learn.microsoft.com/windows/deployment/windows-autopatch/prepare/windows-autopatch-prerequisites" target="_blank" rel="noreferrer">Windows Autopatch prerequisites</a> -- search excerpt</li><li>[ESU] <a href="https://learn.microsoft.com/windows/whats-new/extended-security-updates" target="_blank" rel="noreferrer">Extended Security Updates (ESU) program for Windows 10</a> -- search excerpt</li><li>[LIFE] <a href="https://learn.microsoft.com/lifecycle/faq/windows" target="_blank" rel="noreferrer">Lifecycle FAQ - Windows</a> -- search excerpt</li><li>[ZT] <a href="https://learn.microsoft.com/security/zero-trust/copilots/zero-trust-microsoft-365-copilot" target="_blank" rel="noreferrer">Apply principles of Zero Trust to Microsoft Copilot (steps 2 to 5 describe device management and Windows protection capabilities)</a> -- fetched</li></ul><p>Every item is <strong>manual</strong>: it is exported as a question and scored only when answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>).</p><h2 id="the-enumeration-—-34-items-across-6-groups" tabindex="-1">The enumeration — 34 items across 6 groups <a class="header-anchor" href="#the-enumeration-—-34-items-across-6-groups" aria-label="Permalink to &quot;The enumeration — 34 items across 6 groups&quot;">​</a></h2><h3 id="plan-and-servicing-strategy-win11-pl-—-6-items" tabindex="-1">Plan and servicing strategy (WIN11-PL) — 6 items <a class="header-anchor" href="#plan-and-servicing-strategy-win11-pl-—-6-items" aria-label="Permalink to &quot;Plan and servicing strategy (WIN11-PL) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-PL-01</td><td>A Windows 11 deployment plan exists, with scope, schedule and a process manager who can pause it</td><td>Manual</td><td>PLAN, RDY</td></tr><tr><td>WIN11-PL-02</td><td>The roles the deployment needs are filled (application owners, end-user computing, operations, security, stakeholders)</td><td>Manual</td><td>RDY</td></tr><tr><td>WIN11-PL-03</td><td>Readiness criteria and go or no-go thresholds are defined, including acceptable call and incident trends</td><td>Manual</td><td>RDY, INF</td></tr><tr><td>WIN11-PL-04</td><td>A servicing strategy with a calendar is defined, and the lifecycle of the edition in use is known</td><td>Manual</td><td>STRAT, PLAN</td></tr><tr><td>WIN11-PL-05</td><td>Every device still on Windows 10 has a recorded decision now that Windows 10 has reached end of support (2025-10-14)</td><td>Manual</td><td>ESU, LIFE</td></tr><tr><td>WIN11-PL-06</td><td>Windows Insider Program for Business, Release Preview channel, is used to validate infrastructure and applications ahead of releases</td><td>Manual</td><td>PLAN</td></tr></tbody></table><h3 id="hardware-eligibility-win11-hw-—-8-items" tabindex="-1">Hardware eligibility (WIN11-HW) — 8 items <a class="header-anchor" href="#hardware-eligibility-win11-hw-—-8-items" aria-label="Permalink to &quot;Hardware eligibility (WIN11-HW) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-HW-01</td><td>Every device is inventoried and assessed against the Windows 11 hardware requirements</td><td>Manual</td><td>REQ, PLAN</td></tr><tr><td>WIN11-HW-02</td><td>A readiness report is used for managed devices (Intune endpoint analytics, Configuration Manager tenant attach, or equivalent)</td><td>Manual</td><td>WFA, UPG</td></tr><tr><td>WIN11-HW-03</td><td>Devices reported as not capable or unknown have an owner and an action</td><td>Manual</td><td>WFA</td></tr><tr><td>WIN11-HW-04</td><td>Capable devices with TPM or Secure Boot switched off in firmware are found and fixed</td><td>Manual</td><td>REQ</td></tr><tr><td>WIN11-HW-05</td><td>The hardware refresh plan prioritises devices that cannot upgrade</td><td>Manual</td><td>PLAN</td></tr><tr><td>WIN11-HW-06</td><td>Virtual machines meet the Windows 11 virtual machine requirements</td><td>Manual</td><td>REQ</td></tr><tr><td>WIN11-HW-07</td><td>Windows 10 devices meet the direct upgrade prerequisites, and S mode devices have been switched out</td><td>Manual</td><td>REQ</td></tr><tr><td>WIN11-HW-08</td><td>Feature-specific hardware needs of the organisation are checked (Windows Hello, Teams peripherals, Client Hyper-V, BitLocker to Go)</td><td>Manual</td><td>REQ</td></tr></tbody></table><h3 id="applications-and-peripherals-win11-ap-—-5-items" tabindex="-1">Applications and peripherals (WIN11-AP) — 5 items <a class="header-anchor" href="#applications-and-peripherals-win11-ap-—-5-items" aria-label="Permalink to &quot;Applications and peripherals (WIN11-AP) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-AP-01</td><td>Applications are inventoried and classified as critical, important or not important, with priority and severity defined</td><td>Manual</td><td>RDY</td></tr><tr><td>WIN11-AP-02</td><td>Each critical and important application has an owner and a test plan</td><td>Manual</td><td>RDY, TEST</td></tr><tr><td>WIN11-AP-03</td><td>Applications were tested on Windows 11 using the Microsoft testing guidelines, including the upgrade scenario</td><td>Manual</td><td>TEST</td></tr><tr><td>WIN11-AP-04</td><td>App Assure is used for compatibility issues the organisation cannot resolve</td><td>Manual</td><td>PLAN</td></tr><tr><td>WIN11-AP-05</td><td>Drivers, printers, scanners and line-of-business hardware were validated for Windows 11</td><td>Manual</td><td>PLAN, RDY</td></tr></tbody></table><h3 id="management-deployment-and-update-control-win11-mg-—-7-items" tabindex="-1">Management, deployment and update control (WIN11-MG) — 7 items <a class="header-anchor" href="#management-deployment-and-update-control-win11-mg-—-7-items" aria-label="Permalink to &quot;Management, deployment and update control (WIN11-MG) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-MG-01</td><td>Endpoint management tools are current and support Windows 11</td><td>Manual</td><td>INF, PLAN</td></tr><tr><td>WIN11-MG-02</td><td>Devices are Microsoft Entra joined or hybrid joined and enrolled for management</td><td>Manual</td><td>AP, UPG</td></tr><tr><td>WIN11-MG-03</td><td>Feature update policies target Windows 11, and the handling of devices that cannot run it is decided</td><td>Manual</td><td>UPG</td></tr><tr><td>WIN11-MG-04</td><td>Windows Autopatch rings or an equivalent staged rollout is configured, and the licence and edition prerequisites are met</td><td>Manual</td><td>AP, STRAT</td></tr><tr><td>WIN11-MG-05</td><td>Existing update policies, administrative templates and WSUS settings were reviewed for conflict with the new policies</td><td>Manual</td><td>INF</td></tr><tr><td>WIN11-MG-06</td><td>The deployment method is chosen: in-place upgrade through feature updates, or new and reprovisioned devices</td><td>Manual</td><td>PLAN</td></tr><tr><td>WIN11-MG-07</td><td>Deployment progress, failures and safeguard holds are monitored through update reporting</td><td>Manual</td><td>PLAN, UPG</td></tr></tbody></table><h3 id="security-baseline-win11-sc-—-4-items" tabindex="-1">Security baseline (WIN11-SC) — 4 items <a class="header-anchor" href="#security-baseline-win11-sc-—-4-items" aria-label="Permalink to &quot;Security baseline (WIN11-SC) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-SC-01</td><td>Microsoft security baselines for Windows 11 are applied and kept current</td><td>Manual</td><td>INF</td></tr><tr><td>WIN11-SC-02</td><td>Device protection features are enabled: BitLocker, Windows Hello for Business, Defender Firewall, SmartScreen, application control</td><td>Manual</td><td>ZT</td></tr><tr><td>WIN11-SC-03</td><td>Compliance policies and Conditional Access require healthy, compliant devices</td><td>Manual -- Conditional Access policies and device compliance are not in collect.json</td><td>ZT</td></tr><tr><td>WIN11-SC-04</td><td>The security team reviewed and approved the baseline and tools before pilot</td><td>Manual</td><td>RDY</td></tr></tbody></table><h3 id="operations-and-user-readiness-win11-op-—-4-items" tabindex="-1">Operations and user readiness (WIN11-OP) — 4 items <a class="header-anchor" href="#operations-and-user-readiness-win11-op-—-4-items" aria-label="Permalink to &quot;Operations and user readiness (WIN11-OP) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WIN11-OP-01</td><td>Support readiness is in place: documentation, process changes and a defined rollback</td><td>Manual</td><td>RDY, INF</td></tr><tr><td>WIN11-OP-02</td><td>Users are told what changes and how to get help</td><td>Manual</td><td>RDY</td></tr><tr><td>WIN11-OP-03</td><td>A pilot group is representative of the organisation before broad deployment</td><td>Manual</td><td>RDY, STRAT</td></tr><tr><td>WIN11-OP-04</td><td>Ongoing servicing is planned: monthly quality updates and an annual feature update</td><td>Manual</td><td>PLAN, STRAT</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Plan and servicing strategy</td><td>6</td><td>0</td><td>6</td></tr><tr><td>Hardware eligibility</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Applications and peripherals</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Management, deployment and update control</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Security baseline</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Operations and user readiness</td><td>4</td><td>0</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>34</strong></td><td><strong>0</strong></td><td><strong>34</strong></td></tr></tbody></table><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Everything below needs a Microsoft Graph app registration with read-only application permissions and tenant admin consent, a new collect section for device data, and a gate on each rule so a tenant that was not read reports Not assessed instead of Pass. Intune data covers only devices enrolled in Intune, co-managed, or tenant attached.</p><table tabindex="0"><thead><tr><th>Items</th><th>What would be read</th><th>Interface and permission</th></tr></thead><tbody><tr><td>WIN11-HW-01, HW-02, HW-03</td><td>Windows 11 hardware readiness for each device and the top hardware blockers</td><td>Microsoft Graph v1.0 Intune endpoint analytics: <code>userExperienceAnalyticsWorkFromAnywhereDevice</code> (<code>upgradeEligibility</code> is <code>upgraded</code>, <code>unknown</code>, <code>notCapable</code> or <code>capable</code>) and <code>userExperienceAnalyticsWorkFromAnywhereHardwareReadinessMetric</code> (<code>totalDeviceCount</code>, <code>upgradeEligibleDeviceCount</code> and the failed-check percentages for RAM, storage and processor cores). The read permission for these resources was not confirmed in this pass; <code>DeviceManagementManagedDevices.Read.All</code> is the documented read permission for the sibling managed device APIs.</td></tr><tr><td>WIN11-HW-07, MG-02, PL-05</td><td>Operating system version, edition and join state of each device</td><td>Microsoft Graph v1.0 <code>GET /deviceManagement/managedDevices</code> (<code>operatingSystem</code>, <code>osVersion</code>, <code>complianceState</code>, <code>managementAgent</code>); <code>DeviceManagementManagedDevices.Read.All</code>. The Intune report <code>DevicesWithInventory</code> also carries <code>OSVersion</code>, <code>JoinType</code>, <code>SkuFamily</code>, <code>ProcessorArchitecture</code> and the TPM fields.</td></tr><tr><td>WIN11-MG-03, MG-04, MG-07</td><td>Feature update policies, rings and deployment progress</td><td>Windows Autopatch in Microsoft Graph: <code>admin/windows/updates/deployments</code> and the catalog entries, plus the policy and ring resources in beta (<code>featureUpdatePolicy</code>, <code>featureUpdateRing</code>). The feature update APIs use the beta endpoint and are subject to change.</td></tr><tr><td>WIN11-SC-03</td><td>Conditional Access that requires compliant devices, and Intune compliance policy</td><td>Microsoft Graph v1.0 <code>GET /identity/conditionalAccess/policies</code>; <code>Policy.Read.All</code>. Compliance policy APIs were not researched in this pass.</td></tr></tbody></table><p>Items about planning, applications, people and process (WIN11-PL, WIN11-AP, WIN11-OP) have no API behind them and stay manual in any version. Application compatibility results come from testing, not from an inventory call.</p>',33)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
